DO $$ DECLARE o uuid; o2 uuid; sid uuid; n text; m uuid; failed boolean; BEGIN
IF (SELECT sequence FROM public.document_sequences WHERE tenant_id=public.active_tenant_id() AND client_code='*' AND document_type='invoice')<>166 THEN RAISE EXCEPTION 'FAIL seed 166'; END IF;
o:=public.save_sales_document('orders',NULL,'{"client_name":"Kuilo Dining And Venue","document_date":"2026-01-01"}','[{"item_name":"Uji rollback","qty":1,"price":1}]');
n:=public.issue_invoice(o); IF n<>'167/SDY/INV/KUILODIN/'||to_char(now() AT TIME ZONE 'Asia/Jakarta','MMYYYY') THEN RAISE EXCEPTION 'FAIL nomor 167 tanggal terbit: %',n; END IF;
IF (SELECT order_date FROM public.orders WHERE id=o)<>'2026-01-01'::date OR (SELECT invoice_date FROM public.orders WHERE id=o)<>'2026-01-01'::date THEN RAISE EXCEPTION 'FAIL tanggal berubah'; END IF;
o2:=public.save_sales_document('orders',NULL,'{"client_name":"DNA","document_date":"2026-01-01"}','[{"item_name":"Uji rollback","qty":1,"price":1}]');
n:=public.issue_invoice(o2); IF n<>'168/SDY/INV/DNA/'||to_char(now() AT TIME ZONE 'Asia/Jakarta','MMYYYY') THEN RAISE EXCEPTION 'FAIL nomor 168'; END IF;
sid:=public.create_shipment_atomic(o); IF (SELECT stored_by FROM public.shipments WHERE id=sid) IS NOT NULL OR (SELECT delivery_by FROM public.shipments WHERE id=sid) IS NOT NULL THEN RAISE EXCEPTION 'FAIL UUID pembuat'; END IF;
IF (SELECT do_number FROM public.shipments WHERE id=sid)<>'167/SDY/DO/KUILODIN/'||to_char(now() AT TIME ZONE 'Asia/Jakarta','MMYYYY') THEN RAISE EXCEPTION 'FAIL DO'; END IF;
SELECT id INTO m FROM public.shipment_team_options() LIMIT 1; PERFORM public.assign_shipment_team(sid,m,m);
IF (SELECT stored_by FROM public.shipments WHERE id=sid) IS DISTINCT FROM (SELECT name FROM public.shipment_team_options() WHERE id=m) THEN RAISE EXCEPTION 'FAIL snapshot nama'; END IF;
PERFORM public.assign_shipment_team(sid,NULL,NULL);
failed:=false; BEGIN PERFORM public.assign_shipment_team(sid,'33333333-3333-4333-8333-333333333333',NULL); EXCEPTION WHEN OTHERS THEN failed:=SQLERRM LIKE '%tidak berizin%'; END; IF NOT failed THEN RAISE EXCEPTION 'FAIL member lintas tenant'; END IF;
PERFORM set_config('phase2c.shipment',sid::text,true);
END $$;
RESET ROLE;
