SET LOCAL ROLE authenticated;
DO $$ DECLARE failed boolean:=false; BEGIN BEGIN PERFORM public.assign_shipment_team(current_setting('phase2c.shipment')::uuid,NULL,NULL); EXCEPTION WHEN OTHERS THEN failed:=SQLERRM='Pengiriman tidak berizin'; END; IF NOT failed THEN RAISE EXCEPTION 'FAIL tanpa modul'; END IF; END $$;
SET LOCAL ROLE anon;
DO $$ DECLARE failed boolean:=false; BEGIN BEGIN PERFORM public.assign_shipment_team(current_setting('phase2c.shipment')::uuid,NULL,NULL); EXCEPTION WHEN insufficient_privilege THEN failed:=true; END; IF NOT failed THEN RAISE EXCEPTION 'FAIL anon'; END IF; END $$;
