DO $$ BEGIN IF public.sales_sequence_value('123456') IS NOT NULL OR public.sales_sequence_value('PO-2026-0148') IS NOT NULL OR public.sales_sequence_value('invalid') IS NOT NULL OR public.sales_sequence_value('166/SDY/INV/DNA/082026')<>166 OR public.sales_sequence_value('INV/KUILO/2026/10/1')<>1 THEN RAISE EXCEPTION 'FAIL parser'; END IF; IF EXISTS(SELECT 1 FROM public.shipments WHERE stored_by ~* '^[0-9a-f]{8}-[0-9a-f-]{27}$' OR delivery_by ~* '^[0-9a-f]{8}-[0-9a-f-]{27}$') THEN RAISE EXCEPTION 'FAIL UUID tersisa'; END IF; END $$;
